:root {
  --detail-text-color: #246875;
  --detail-border: #57919B;
  --detail-icon-color: #7D96A1;

  --detail-fill-light: #FAFCFD;
  --detail-fill-middle: #F4F7FA;
  --detail-fill-base: #E8F1F3;

  --detail-hover-border: #397985;
  --detail-hover-light: #F2F9F9;
  --detail-hover-base: #DCECEF;

  --detail-font-size: 22px;
  --detail-icon-size: 21px;
  --detail-gap: 11px;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.detail-widget,
.detail-widget * {
  box-sizing: border-box;
}

.detail-widget {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  background: transparent;

  font-family:
    "Bahnschrift",
    "DIN Alternate",
    Consolas,
    "Liberation Mono",
    monospace;

  font-style: normal;
  font-variant-ligatures: none;
}

/* El borde coincide con los límites del widget. */
.detail-button {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;

  appearance: none;
  border: 2px solid var(--detail-border);
  border-radius: 8px;

  background: linear-gradient(
    155deg,
    var(--detail-fill-light) 0%,
    var(--detail-fill-middle) 55%,
    var(--detail-fill-base) 100%
  );

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 -1px 2px rgba(1, 82, 79, 0.10);

  color: var(--detail-text-color);
  font-family: inherit;
  cursor: pointer;
  pointer-events: auto;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;

  transition:
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.detail-content {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  gap: var(--detail-gap);

  pointer-events: none;
  transform: scale(1);
  transform-origin: center;
}

.detail-button-text {
  font-size: var(--detail-font-size);
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.detail-button-icon {
  display: block;
  flex: 0 0 auto;

  width: var(--detail-icon-size);
  height: var(--detail-icon-size);

  fill: none;
  stroke: var(--detail-icon-color);
  stroke-width: 2.3;
  stroke-linecap: round;
  stroke-linejoin: round;

  transition: stroke 150ms ease;
}

@media (hover: hover) {
  .detail-button:hover {
    border-color: var(--detail-hover-border);

    background: linear-gradient(
      155deg,
      var(--detail-hover-light) 0%,
      var(--detail-hover-base) 100%
    );

    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.9),
      inset 0 -1px 3px rgba(1, 82, 79, 0.14);
  }

  .detail-button:hover .detail-button-icon {
    stroke: var(--detail-hover-border);
  }
}

/* Foco interior: no necesita margen exterior. */
.detail-button:focus-visible {
  outline: 2px solid var(--detail-hover-border);
  outline-offset: -5px;
}

/* Hundimiento sin cambiar las dimensiones del botón. */
.detail-button:active {
  box-shadow:
    inset 0 2px 5px rgba(1, 82, 79, 0.25),
    inset 0 -1px 0 rgba(255, 255, 255, 0.45);
}

.detail-button:active .detail-content {
  transform: scale(0.98);
}

@media (prefers-reduced-motion: reduce) {
  .detail-button,
  .detail-button-icon {
    transition: none;
  }
}

