"use strict";

(function () {
  const BASE_WIDTH = 276;
  const BASE_HEIGHT = 58;

  let container = null;
  let button = null;
  let latestWidget = null;
  let resizeObserver = null;

  function resizeContent() {
    if (!container || !button) return;

    const width = button.clientWidth;
    const height = button.clientHeight;

    if (width <= 0 || height <= 0) return;

    /*
     * El botón siempre llena el widget.
     * Solo el texto, el símbolo y su separación
     * se ajustan proporcionalmente al espacio disponible.
     */
    const scale = Math.min(
      width / (BASE_WIDTH - 4),
      height / (BASE_HEIGHT - 4)
    );

    container.style.setProperty(
      "--detail-font-size",
      (22 * scale) + "px"
    );

    container.style.setProperty(
      "--detail-icon-size",
      (21 * scale) + "px"
    );

    container.style.setProperty(
      "--detail-gap",
      (11 * scale) + "px"
    );
  }

  function render(w) {
    if (!button) return;

    const name =
      w && typeof w.name === "string"
        ? w.name.trim()
        : "";

    button.setAttribute(
      "aria-label",
      name ? "Ver detalle de " + name : "Ver detalle"
    );
  }

  window.onWidgetUpdate = function (w) {
    latestWidget = w;
    render(w);
  };

  function initialize() {
    container = document.querySelector(".detail-widget");
    button = document.querySelector(".detail-button");

    if (!container || !button) return;

    render(latestWidget || window.WIDGET || null);
    resizeContent();

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(resizeContent);
      resizeObserver.observe(button);
    } else {
      window.addEventListener("resize", resizeContent);
    }

    /*
     * Sin variables del PLC ni acción de clic.
     * Los efectos de interacción se controlan con CSS.
     */
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
